import json
import sys

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        all_keys = set(a.keys()) | set(b.keys())
        for key in all_keys:
            if key in a and key in b:
                result[key] = deep_merge(a[key], b[key])
            elif key in a:
                result[key] = a[key]
            else:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = list(a)
        for item in b:
            if item not in result:
                result.append(item)
        return result
    else:
        return b

