import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String path = "/tmp/…/app.log";
        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorCountsByComponent = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        Pattern p = Pattern.compile("\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.*)");
        try (BufferedReader br = Files.newBufferedReader(Paths.get(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                Matcher m = p.matcher(line);
                if (!m.matches()) continue;
                String timestamp = m.group(1);
                String level = m.group(2);
                String component = m.group(3);
                String message = m.group(4);

                levelCounts.merge(level, 1, Integer::sum);

                int hour = Integer.parseInt(timestamp.substring(11, 13));
                hourCounts.merge(hour, 1, Integer::sum);

                if ("ERROR".equals(level)) {
                    errorCountsByComponent.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }
            }
        } catch (IOException e) {
            // file may be missing; continue with empty data
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        if (levelCounts.isEmpty()) {
        } else {
            for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
                System.out.println("  " + e.getKey() + ": " + e.getValue());
            }
        }
        System.out.println();
        String compMost = "";
        int compMostCount = 0;
        if (!errorCountsByComponent.isEmpty()) {
            for (Map.Entry<String, Integer> e : errorCountsByComponent.entrySet()) {
                if (e.getValue() > compMostCount || (e.getValue() == compMostCount && e.getKey().compareTo(compMost) < 0)) {
                    compMost = e.getKey();
                    compMostCount = e.getValue();
                }
            }
        }
        System.out.println("Component with Most Errors: " + compMost + " (" + compMostCount + " errors)");
        System.out.println();
        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();
        int busiestHour = 0;
        int busiestCount = 0;
        if (!hourCounts.isEmpty()) {
            for (Map.Entry<Integer, Integer> e : hourCounts.entrySet()) {
                int h = e.getKey();
                int c = e.getValue();
                if (c > busiestCount || (c == busiestCount && h < busiestHour)) {
                    busiestHour = h;
                    busiestCount = c;
                }
            }
        }
        System.out.printf("Busiest Hour: %02d:00 (%d entries)%n", busiestHour, busiestCount);
    }
}

