use std::collections::HashMap;
use std::fs::File;
use std::io::{BufRead, BufReader};

fn comma_sep_int_str(s: &str) -> String {
    let sign = if s.starts_with('-') { "-" } else { "" };
    let digits = s.trim_start_matches('-');
    let chars: Vec<char> = digits.chars().rev().collect();
    let mut out = String::new();
    for (i, ch) in chars.iter().enumerate() {
        if i > 0 && i % 3 == 0 {
            out.push(',');
        }
        out.push(*ch);
    }
    let out: String = out.chars().rev().collect();
    format!("{}{}", sign, out)
}

fn format_avg(val: f64) -> String {
    let s = format!("{:.2}", val);
    let mut parts = s.split('.').collect::<Vec<&str>>();
    let int_comma = comma_sep_int_str(parts[0]);
    format!("{}.{}", int_comma, parts[1])
}

fn format_int_money(n: i64) -> String {
    format!("${}", comma_sep_int_str(&n.to_string()))
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path).expect("cannot open file");
    let reader = BufReader::new(file);

    let mut dept_sum: HashMap<String, i64> = HashMap::new();
    let mut dept_cnt: HashMap<String, usize> = HashMap::new();

    let mut highest_salary: i64 = i64::MIN;
    let mut highest_name = String::new();
    let mut total_budget: i64 = 0;

    for (i, line) in reader.lines().enumerate() {
        let line = line.unwrap();
        if i == 0 { continue; }
        let line = line.trim();
        if line.is_empty() { continue; }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 4 { continue; }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: i64 = fields[3].parse().unwrap_or(0);

        *dept_sum.entry(department.clone()).or_insert(0) += salary;
        *dept_cnt.entry(department.clone()).or_insert(0) += 1;

        total_budget += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    let mut depts: Vec<String> = dept_sum.keys().cloned().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!("");
    println!("Average Salary by Department:");
    for dept in &depts {
        let sum = dept_sum.get(dept).copied().unwrap_or(0);
        let cnt = *dept_cnt.get(dept).unwrap_or(&1);
        let avg = sum as f64 / cnt as f64;
        println!("  {}: ${}", dept, format_avg(avg));
    }
    println!("");
    println!("Highest Paid: {} ({})", highest_name, format_int_money(highest_salary));
    println!("");
    println!("Departments with >2 employees:");
    let mut big_depts: Vec<(String, usize)> = dept_cnt.iter()
        .filter(|(_, &c)| c > 2)
        .map(|(d, &c)| (d.clone(), c))
        .collect();
    big_depts.sort_by(|a, b| a.0.cmp(&b.0));
    for (dept, cnt) in big_depts {
        println!("  {} ({} employees)", dept, cnt);
    }
    println!("");
    println!("Total Budget: {}", format_int_money(total_budget));
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Product {
        String name;
        double price;
        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) throws Exception {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder(URI.create("http://127.0.0.1:18923/api/products"))
                .GET()
                .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        String json = response.body();

        List<Product> products = new ArrayList<>();
        Pattern objPat = Pattern.compile("\\{[^}]*\\}");
        Matcher objMatcher = objPat.matcher(json);
        Pattern namePat = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]*)\"");
        Pattern pricePat = Pattern.compile("\"price\"\\s*:\\s*([0-9]*\\.?[0-9]+)");
        while (objMatcher.find()) {
            String obj = objMatcher.group();
            Matcher nameMatcher = namePat.matcher(obj);
            Matcher priceMatcher = pricePat.matcher(obj);
            if (nameMatcher.find() && priceMatcher.find()) {
                String name = nameMatcher.group(1);
                double price = Double.parseDouble(priceMatcher.group(1));
                products.add(new Product(name, price));
            }
        }

        List<Product> filtered = new ArrayList<>();
        for (Product p : products) {
            if (p.price > 50.00) {
                filtered.add(p);
            }
        }
        filtered.sort(Comparator.comparing(p -> p.name));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        for (Product p : filtered) {
            System.out.println(p.name + ": $" + String.format("%.2f", p.price));
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        double total = 0.0;
        for (Product p : filtered) total += p.price;
        System.out.println("Total: $" + String.format("%.2f", total));
    }
}

import * as http from 'http';

type Product = {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
};

function fetchProducts(): Promise<Product[]> {
  return new Promise((resolve, reject) => {
    const req = http.get('http://127.0.0.1:18923/api/products', (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        try {
          const products = JSON.parse(data) as Product[];
          resolve(products);
        } catch (e) {
          reject(e);
        }
      });
    });
    req.on('error', reject);
  });
}

async function main() {
  const products = await fetchProducts();
  const filtered = products
    .filter(p => p.price > 50)
    .sort((a, b) => a.name.localeCompare(b.name));

  console.log('=== Filtered Products (price > $50.00) ===');
