import json
import heapq

GRAPH_PATH = "/tmp/…/graph.json"

def main():
    with open(GRAPH_PATH, "r") as f:
        data = json.load(f)

    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    adj = {node: [] for node in nodes}
    for e in edges:
        u = e["from"]
        v = e["to"]
        w = e["weight"]
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w))
        adj[v].append((u, w))

    start = "A"
    if start not in adj:
        adj[start] = []

    dist = {node: float("inf") for node in adj}
    dist[start] = 0
    heap = [(0, start)]
    visited = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    # Ensure all original nodes are in dist
    for node in nodes:
        if node not in dist:
            dist[node] = float("inf")

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist.get(node, float("inf"))
        if d == float("inf"):
            d_str = "inf"
        else:
            # print as int if integral
            if isinstance(d, float) and d.is_integer():
                d_str = str(int(d))
            else:
                d_str = str(d)
        print(f"A -> {node}: {d_str}")

