#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 1024
#define MAX_NAME 256

typedef struct {
    char name[MAX_NAME];
    long long sum;
    int count;
} Dept;

void format_int_commas(long long v, char *out) {
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%lld", v);
    if (len <= 0) { out[0] = '\0'; return; }
    int commas = (len - 1) / 3;
    int newlen = len + commas;
    out[newlen] = '\0';
    int i = len - 1, j = newlen - 1, c = 0;
    while (i >= 0) {
        out[j--] = buf[i--];
        c++;
        if (c == 3 && i >= 0) {
            out[j--] = ',';
            c = 0;
        }
    }
}

void format_avg(double avg, char *out) {
    long long int_part = (long long)floor(avg);
    double frac = avg - (double)int_part;
    int cents = (int)round(frac * 100.0);
    if (cents >= 100) { int_part += 1; cents -= 100; }
    if (cents < 0) cents = 0;
    char intbuf[64];
    format_int_commas(int_part, intbuf);
    sprintf(out, "$%s.%02d", intbuf, cents);
}

int cmp_dept(const void *a, const void *b) {
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

char *trim(char *s) {
    while (*s && (*s==' ' || *s=='\t' || *s=='\r')) s++;
    char *e = s + strlen(s) - 1;
    while (e >= s && (*e==' ' || *e=='\t' || *e=='\r' || *e=='\n')) *e-- = '\0';
    return s;
}

int main(void) {
    const char *path = "/tmp/…/employees.csv";
    FILE *f = fopen(path, "r");
    if (!f) return 1;
    char line[MAX_LINE];
    fgets(line, sizeof(line), f); /* header */

    Dept *depts = NULL;
    int dept_cnt = 0;
    int dept_cap = 0;

    char best_name[MAX_NAME] = "";
    long long best_salary = -1;
    long long total_budget = 0;

    while (fgets(line, sizeof(line), f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;
        char *tok[6];
        int t = 0;
        char *saveptr;
        char *p = strtok_r(line, ",", &saveptr);
        while (p && t < 6) {
            tok[t++] = trim(p);
            p = strtok_r(NULL, ",", &saveptr);
        }
        if (t < 6) continue;
        char *name = tok[1];
        char *dept_name = tok[2];
        long long salary = strtoll(tok[3], NULL, 10);

        total_budget += salary;
        if (salary > best_salary) {
            best_salary = salary;
            strncpy(best_name, name, MAX_NAME-1);
            best_name[MAX_NAME-1] = '\0';
        }

        int idx = -1;
        for (int i = 0; i < dept_cnt; i++) {
            if (strcmp(depts[i].name, dept_name) == 0) { idx = i; break; }
        }
        if (idx == -1) {
            if (dept_cnt == dept_cap) {
                dept_cap = dept_cap ? dept_cap*2 : 16;
                depts = realloc(depts, dept_cap * sizeof(Dept));
            }
            strncpy(depts[dept_cnt].name, dept_name, MAX_NAME-1);
            depts[dept_cnt].name[MAX_NAME-1] = '\0';
            depts[dept_cnt].sum = salary;
            depts[dept_cnt].count = 1;
            dept_cnt++;
        } else {
            depts[idx].sum += salary;
            depts[idx].count += 1;
        }
    }
    fclose(f);

    qsort(depts, dept_cnt, sizeof(Dept), cmp_dept);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_cnt; i++) {
        double avg = (double)depts[i].sum / depts[i].count;
        char avgbuf[64];
        format_avg(avg, avgbuf);
        printf("  %s: %s\n", depts[i].name, avgbuf);
    }
    printf("\n");

    char bestbuf[64];
    format_int_commas(best_salary, bestbuf);
    printf("Highest Paid: %s ($%s)\n\n", best_name, bestbuf);

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_cnt; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    char totalbuf[64];
    format_int_commas(total_budget, totalbuf);
    printf("Total Budget: $%s\n", totalbuf);

    free(depts);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define PATH "/tmp/…/app.log"
#define MAX_LINE 4096

typedef struct {
    char *name;
    int count;
} LevelEntry;

typedef struct {
    char *name;
    int count;
} CompEntry;

int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}
int cmp_level(const void *a, const void *b) {
    return strcmp(((LevelEntry*)a)->name, ((LevelEntry*)b)->name);
}

int main(void) {
    FILE *f = fopen(PATH, "r");
    if (!f) return 1;
    char line[MAX_LINE];
    int hour_counts[24] = {0};

    LevelEntry *levels = NULL;
    size_t levels_n = 0, levels_cap = 0;

    CompEntry *comps = NULL;
    size_t comps_n = 0, comps_cap = 0;

    char **err_msgs = NULL;
    size_t err_n = 0, err_cap = 0;

    while (fgets(line, sizeof(line), f)) {
        int year, month, day, hour, min, sec;
        char level[32];
        char component[256];
        char message[2048];
        int scanned = sscanf(line,
            "[%d-%d-%d %d:%d:%d] %31s (%255[^)]) - %[^\n]",
            &year, &month, &day, &hour, &min, &sec,
            level, component, message);
        if (scanned < 9) continue;
        if (hour >= 0 && hour < 24) hour_counts[hour]++;

        /* levels */
        int found = 0;
        for (size_t i = 0; i < levels_n; i++) {
            if (strcmp(levels[i].name, level) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (levels_n == levels_cap) {
                levels_cap = levels_cap ? levels_cap * 2 : 16;
                levels = realloc(levels, levels_cap * sizeof(LevelEntry));
            }
            levels[levels_n].name = strdup(level);
            levels[levels_n].count = 1;
            levels_n++;
        }

        if (strcmp(level, "ERROR") == 0) {
            /* component error count */
            int cfound = 0;
            for (size_t i = 0; i < comps_n; i++) {
                if (strcmp(comps[i].name, component) == 0) {
                    comps[i].count++;
                    cfound = 1;
                    break;
                }
            }
            if (!cfound) {
                if (comps_n == comps_cap) {
                    comps_cap = comps_cap ? comps_cap * 2 : 16;
                    comps = realloc(comps, comps_cap * sizeof(CompEntry));
                }
                comps[comps_n].name = strdup(component);
                comps[comps_n].count = 1;
                comps_n++;
            }
            /* error message */
            if (err_n == err_cap) {
                err_cap = err_cap ? err_cap * 2 : 256;
                err_msgs = realloc(err_msgs, err_cap * sizeof(char*));
            }
            err_msgs[err_n++] = strdup(message);
        }
    }
    fclose(f);

    qsort(levels, levels_n, sizeof(LevelEntry), cmp_level);

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    for (size_t i = 0; i < levels_n; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");

    char best_comp[256] = "";
    int best_cnt = 0;
    for (size_t i = 0; i < comps_n; i++) {
        if (comps[i].count > best_cnt) {
            best_cnt = comps[i].count;
            strncpy(best_comp, comps[i].name, sizeof(best_comp)-1);
        }
    }
    printf("Component with Most Errors: %s (%d errors)\n\n", best_comp, best_cnt);

    printf("Unique Error Messages:\n");
    if (err_n > 0) {
        qsort(err_msgs, err_n, sizeof(char*), cmp_str);
        char *prev = NULL;
        for (size_t i = 0; i < err_n; i++) {
            if (prev && strcmp(err_msgs[i], prev) == 0) continue;
            printf("  - %s\n", err_msgs[i]);
            prev = err_msgs[i];
        }
    }
    printf("\n");

    int best_hour = 0;
    int best_hour_cnt = -1;
    for (int h = 0; h < 24; h++) {
        if (hour_counts[h] > best_hour_cnt) {
            best_hour_cnt = hour_counts[h];
            best_hour = h;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, best_hour_cnt);

    return 0;
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Edge {
        String to;
        int w;
        Edge(String to, int w) { this.to = to; this.w = w; }
    }
    static class NodeDist implements Comparable<NodeDist> {
        String node;
        long dist;
        NodeDist(String node, long dist) { this.node = node; this.dist = dist; }
        public int compareTo(NodeDist o) { return Long.compare(this.dist, o.dist); }
    }

    public static void main(String[] args) throws IOException {
        String path = "/tmp/…/graph.json";
        String content = Files.readString(Path.of(path));

        List<String> nodes = new ArrayList<>();
        Pattern nodesPat = Pattern.compile("\"nodes\"\\s*:\\s*\\[(.*?)]", Pattern.DOTALL);
        Matcher m = nodesPat.matcher(content);
        if (m.find()) {
            Matcher sm = Pattern.compile("\"([^\"]+)\"").matcher(m.group(1));
            while (sm.find()) nodes.add(sm.group(1));
        }

        Map<String, List<Edge>> adj = new HashMap<>();
        for (String n : nodes) adj.putIfAbsent(n, new ArrayList<>());

        Pattern edgesPat = Pattern.compile("\"edges\"\\s*:\\s*\\[(.*?)]", Pattern.DOTALL);
        m = edgesPat.matcher(content);
        if (m.find()) {
            String edgesBlock = m.group(1);
            Pattern edgePat = Pattern.compile("\"from\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"to\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"weight\"\\s*:\\s*(\\d+)");
            Matcher em = edgePat.matcher(edgesBlock);
            while (em.find()) {
                String from = em.group(1);
                String to = em.group(2);
                int w = Integer.parseInt(em.group(3));
                adj.computeIfAbsent(from, k -> new ArrayList<>()).add(new Edge(to, w));
                adj.computeIfAbsent(to, k -> new ArrayList<>()).add(new Edge(from, w));
            }
        }

        String source = "A";
        Map<String, Long> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Long.MAX_VALUE);
        if (!dist.containsKey(source)) dist.put(source, Long.MAX_VALUE);
        dist.put(source, 0L);

        PriorityQueue<NodeDist> pq = new PriorityQueue<>();
        pq.offer(new NodeDist(source, 0));

        Set<String> visited = new HashSet<>();
        while (!pq.isEmpty()) {
            NodeDist cur = pq.poll();
            if (visited.contains(cur.node)) continue;
            visited.add(cur.node);
            for (Edge e : adj.getOrDefault(cur.node, Collections.emptyList())) {
                long nd = cur.dist + e.w;
                if (nd < dist.getOrDefault(e.to, Long.MAX_VALUE)) {
                    dist.put(e.to, nd);
                    pq.offer(new NodeDist(e.to, nd));
                }
            }
        }

        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        // ensure source present
        if (!sorted.contains(source)) sorted.add(0, source);
        Collections.sort(sorted);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sorted) {
            long d = dist.getOrDefault(n, Long.MAX_VALUE);
            String out = (d == Long.MAX_VALUE) ? "Infinity" : Long.toString(d);
            System.out.println("A -> " + n + ": " + out);
        }
    }
}

use std::collections::{BTreeSet, HashMap};
use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let path = "/tmp/…/app.log";
    let file = File::open(path).unwrap_or_else(|_| File::open("/dev/null").unwrap());
    let reader = BufReader::new(file);

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_by_component: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in reader.lines() {
        let line = line.unwrap();
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if !line.starts_with('[') {
            continue;
        }
        // find ]
        if let Some(close_bracket) = line.find(']') {
            let ts_part = &line[1..close_bracket];
            let rest = line[close_bracket + 1..].trim_start();
            // level
            let mut split = rest.splitn(2, ' ');
            let level = match split.next() {
                Some(l) => l.to_string(),
                None => continue,
            };
            let after_level = split.next().unwrap_or("").trim_start();
            // component
            if let Some(open_paren) = after_level.find('(') {
                if let Some(close_paren) = after_level[open_paren..].find(')') {
                    let component = after_level[open_paren + 1..open_paren + close_paren].trim().to_string();
                    let after_comp = &after_level[open_paren + close_paren + 1..];
                    let message = if after_comp.starts_with('-') {
                        after_comp[1..].trim_start().to_string()
                    } else {
                        after_comp.trim_start().to_string()
                    };

                    // level counts
                    *level_counts.entry(level.clone()).or_insert(0) += 1;

                    // hour
                    if let Some(space_idx) = ts_part.find(' ') {
                        let time_part = &ts_part[space_idx + 1..];
                        if time_part.len() >= 2 {
                            let hour = &time_part[0..2];
                            let hour_key = format!("{}:00", hour);
                            *hour_counts.entry(hour_key).or_insert(0) += 1;
                        }
                    }

                    // errors
                    if level.eq_ignore_ascii_case("ERROR") {
                        *error_by_component.entry(component.clone()).or_insert(0) += 1;
                        error_messages.insert(message);
                    }
                }
            }
        }
    }

    // Entries by Level sorted alphabetically
    let mut level_entries: Vec<(String, usize)> = level_counts.into_iter().collect();
    level_entries.sort_by(|a, b| a.0.cmp(&b.0));

    // Component with most errors
    let mut most_error_component = String::from("N/A");
    let mut most_error_count = 0;
    for (comp, cnt) in &error_by_component {
        if *cnt > most_error_count || (*cnt == most_error_count && comp < &most_error_component) {
            most_error_component = comp.clone();
            most_error_count = *cnt;
        }
    }
    if most_error_count == 0 {
        most_error_component = "None".to_string();
    }

    // Busiest hour
    let mut busiest_hour = "00:00".to_string();
    let mut busiest_count = 0;
    let mut hours_vec: Vec<(String, usize)> = hour_counts.into_iter().collect();
    hours_vec.sort_by(|a, b| a.0.cmp(&b.0));
    for (h, c) in &hours_vec {
        if *c > busiest_count {
            busiest_count = *c;
            busiest_hour = h.clone();
        }
    }
    if busiest_count == 0 {
        busiest_hour = "00:00".to_string();
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (lvl, cnt) in &level_entries {
        println!("  {}: {}", lvl, cnt);
    }
    println!();
    println!("Component with Most Errors: {} ({} errors)", most_error_component, most_error_count);
    println!();
    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();
    println!("Busiest Hour: {} ({} entries)", busiest_hour, busiest_count);
}

