import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        try {
            String hostname = runCmd("hostname");
            String os = runCmd("uname", "-s");
            String architecture = runCmd("uname", "-m");
            String username = runCmd("whoami");

            System.out.println("{");
            System.out.println("  \"hostname\": \"" + escapeJson(hostname) + "\",");
            System.out.println("  \"os\": \"" + escapeJson(os) + "\",");
            System.out.println("  \"architecture\": \"" + escapeJson(architecture) + "\",");
            System.out.println("  \"username\": \"" + escapeJson(username) + "\"");
            System.out.println("}");
        } catch (Exception e) {
            System.exit(1);
        }
    }

    private static String runCmd(String... cmd) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder(cmd);
        pb.redirectErrorStream(true);
        Process p = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line).append("\n");
        }
        p.waitFor();
        return sb.toString().trim();
    }

    private static String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}

use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn parse_product(obj: &str) -> Option<Product> {
    let name_key = "\"name\":\"";
    let name_start = obj.find(name_key)? + name_key.len();
    let name_end = obj[name_start..].find('"')? + name_start;
    let name = obj[name_start..name_end].to_string();

    let price_key = "\"price\":";
    let price_start = obj.find(price_key)? + price_key.len();
    let price_rest = &obj[price_start..];
    let price_end = price_rest.find(|c: char| c == ',' || c == '}').unwrap_or(price_rest.len());
    let price_str = price_rest[..price_end].trim();
    let price = price_str.parse::<f64>().ok()?;

    Some(Product { name, price })
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("connect");
    let request = b"GET /api/products HTTP/1.0\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request).expect("write");
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).expect("read");
    let resp = String::from_utf8_lossy(&buf);
    let body = if let Some(idx) = resp.find("\r\n\r\n") {
        &resp[idx + 4..]
    } else {
        &resp
    };

    let mut products = Vec::new();
    let mut rest = body;
    loop {
        if let Some(start) = rest.find('{') {
            let after = &rest[start..];
            if let Some(end) = after.find('}') {
                let obj = &after[..=end];
                if let Some(p) = parse_product(obj) {
                    products.push(p);
                }
                rest = &after[end + 1..];
            } else {
                break;
            }
        } else {
            break;
        }
    }

    let mut filtered: Vec<Product> = products.into_iter().filter(|p| p.price > 50.0).collect();
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
    }
    if !filtered.is_empty() {
        println!();
    }
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|p| p.price).sum();
    println!("Total: ${:.2}", total);
}

use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn parse_product(obj: &str) -> Option<Product> {
    // parse name with whitespace tolerance
    let name_key = "\"name\"";
    let name_idx = obj.find(name_key)?;
    let after_name = &obj[name_idx + name_key.len()..];
    let colon = after_name.find(':')?;
    let after_colon = &after_name[colon + 1..];
    let first_quote = after_colon.find('"')?;
    let name_start = first_quote + 1;
    let name_rest = &after_colon[name_start..];
    let second_quote = name_rest.find('"')?;
    let name = name_rest[..second_quote].to_string();

    // parse price with whitespace tolerance
    let price_key = "\"price\"";
    let price_idx = obj.find(price_key)?;
    let after_price = &obj[price_idx + price_key.len()..];
    let colon_p = after_price.find(':')?;
    let after_colon_p = &after_price[colon_p + 1..];
    let price_trim = after_colon_p.trim_start();
    let end = price_trim.find(|c: char| !c.is_ascii_digit() && c != '.' && c != '-' && c != 'e' && c != 'E' && c != '+').unwrap_or(price_trim.len());
    let price_str = &price_trim[..end];
    let price = price_str.parse::<f64>().ok()?;

    Some(Product { name, price })
}

