import { execSync } from 'child_process';

function run(cmd: string): string {
  const out = execSync(cmd, { encoding: 'utf-8' });
  return out.trim();
}

const hostname = run('hostname');
const os = run('uname -s');
const architecture = run('uname -m');
const username = run('whoami');

const result = {
  hostname,
  os,
  architecture,
  username
};

console.log(JSON.stringify(result, null, 2));

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *run_cmd(const char *cmd) {
    FILE *pipe = popen(cmd, "r");
    if (!pipe) return NULL;
    size_t cap = 256;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) { pclose(pipe); return NULL; }
    int c;
    while ((c = fgetc(pipe)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); pclose(pipe); return NULL; }
            buf = nb;
        }
        buf[len++] = (char)c;
    }
    buf[len] = '\0';
    pclose(pipe);
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r' || buf[len-1] == '\t' || buf[len-1] == ' ')) {
        buf[--len] = '\0';
    }
    return buf;
}

int main(void) {
    char *os_name = run_cmd("uname -s");
    char *arch = run_cmd("uname -m");
    char *user = run_cmd("whoami");
    char *host = run_cmd("hostname");

    if (!os_name || !arch || !user || !host) {
        free(os_name); free(arch); free(user); free(host);
        return 1;
    }

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", host);
    printf("  \"os\": \"%s\",\n", os_name);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", user);
    printf("}\n");

    free(os_name);
    free(arch);
    free(user);
    free(host);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>

typedef struct {
    char name[256];
    double price;
} Product;

int cmp_product(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    return strcmp(pa->name, pb->name);
}

char *read_http_body(int sock) {
    size_t cap = 8192;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    ssize_t n;
    while ((n = read(sock, buf + len, cap - len)) > 0) {
        len += n;
        if (len == cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); return NULL; }
            buf = nb;
        }
    }
    if (len == cap) {
        char *nb = realloc(buf, cap + 1);
        if (!nb) { free(buf); return NULL; }
        buf = nb;
    }
    buf[len] = '\0';
    char *body = strstr(buf, "\r\n\r\n");
    if (body) body += 4;
    else body = buf;
    char *res = strdup(body);
    free(buf);
    return res;
}

int main(void) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) { perror("socket"); return 1; }
    struct sockaddr_in srv;
    memset(&srv, 0, sizeof(srv));
    srv.sin_family = AF_INET;
    srv.sin_port = htons(18923);
    inet_pton(AF_INET, "127.0.0.1", &srv.sin_addr);
    if (connect(sock, (struct sockaddr*)&srv, sizeof(srv)) < 0) {
        perror("connect");
        close(sock);
        return 1;
    }
    const char *req = "GET /api/products HTTP/1.0\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    write(sock, req, strlen(req));
    char *body = read_http_body(sock);
    close(sock);
    if (!body) return 1;

    Product *list = NULL;
    size_t count = 0;
    size_t cap = 0;
    char *p = body;
    while (1) {
        char *obj_start = strchr(p, '{');
        if (!obj_start) break;
        char *obj_end = strchr(obj_start, '}');
        if (!obj_end) break;
        *obj_end = '\0';

        char *name_key = strstr(obj_start, "\"name\"");
        char *price_key = strstr(obj_start, "\"price\"");
        if (name_key && price_key) {
            char *colon = strchr(name_key, ':');
            if (colon) {
                char *q1 = strchr(colon, '"');
                if (q1) {
                    char *q2 = strchr(q1 + 1, '"');
                    if (q2) {
                        size_t nlen = q2 - q1 - 1;
                        if (nlen >= sizeof(((Product*)0)->name)) nlen = sizeof(((Product*)0)->name) - 1;
                        char namebuf[256];
                        memcpy(namebuf, q1 + 1, nlen);
                        namebuf[nlen] = '\0';

                        char *pcolon = strchr(price_key, ':');
                        if (pcolon) {
                            double price = strtod(pcolon + 1, NULL);
                            if (price > 50.0) {
                                if (count == cap) {
                                    cap = cap ? cap * 2 : 16;
                                    Product *nl = realloc(list, cap * sizeof(Product));
                                    if (!nl) { free(list); free(body); return 1; }
                                    list = nl;
                                }
                                strncpy(list[count].name, namebuf, sizeof(list[count].name) - 1);
                                list[count].name[sizeof(list[count].name) - 1] = '\0';
                                list[count].price = price;
                                count++;
                            }
                        }
                    }
                }
            }
        }
        *obj_end = '}';
        p = obj_end + 1;
    }

    if (count > 1) qsort(list, count, sizeof(Product), cmp_product);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    double total = 0.0;
    for (size_t i = 0; i < count; i++) {
        printf("%s: $%.2f\n", list[i].name, list[i].price);
        total += list[i].price;
    }
    printf("Count: %zu\n", count);
    printf("Total: $%.2f\n", total);

    free(list);
    free(body);
    return 0;
}

