    char *p = body;
    while (1) {
        char *obj_start = strchr(p, '{');
        if (!obj_start) break;
        char *obj_end = strchr(obj_start, '}');
        if (!obj_end) break;
        *obj_end = '\0';

        char *name_key = strstr(obj_start, "\"name\"");
        char *price_key = strstr(obj_start, "\"price\"");
        if (name_key && price_key) {
            char *colon = strchr(name_key, ':');
            if (colon) {
                char *q1 = strchr(colon, '"');
                if (q1) {
                    char *q2 = strchr(q1 + 1, '"');
                    if (q2) {
                        size_t nlen = q2 - q1 - 1;
                        if (nlen >= sizeof(((Product*)0)->name)) nlen = sizeof(((Product*)0)->name) - 1;
                        char namebuf[256];
                        memcpy(namebuf, q1 + 1, nlen);
                        namebuf[nlen] = '\0';

                        char *pcolon = strchr(price_key, ':');
                        if (pcolon) {
                            double price = strtod(pcolon + 1, NULL);
                            if (price > 50.0) {
                                if (count == cap) {
                                    cap = cap ? cap * 2 : 16;
                                    Product *nl = realloc(list, cap * sizeof(Product));
                                    if (!nl) { free(list); free(body); return 1; }
                                    list = nl;
                                }
                                strncpy(list[count].name, namebuf, sizeof(list[count].name) - 1);
                                list[count].name[sizeof(list[count].name) - 1] = '\0';
                                list[count].price = price;
                                count++;
                            }
                        }
                    }
                }
            }
        }
        *obj_end = '}';
        p = obj_end + 1;
    }

    if (count > 1) qsort(list, count, sizeof(Product), cmp_product);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    double total = 0.0;
    for (size_t i = 0; i < count; i++) {
        printf("%s: $%.2f\n", list[i].name, list[i].price);
        total += list[i].price;
    }
    printf("\n");
    printf("Count: %zu\n", count);
    printf("Total: $%.2f\n", total);

    free(list);
    free(body);
    return 0;
}

