        case "\r": out += "\\r"
        case "\t": out += "\\t"
        case "\b": out += "\\b"
        case "\f": out += "\\f"
        default:
            if ch.unicodeScalars.allSatisfy({ $0.value < 0x20 }) {
                out += String(format: "\\u%04x", ch.unicodeScalars.first!.value)
            } else {
