    let nextIndent = String(repeating: " ", count: (level + 1) * 2)

    if let dict = value as? [String: Any] {
        if dict.isEmpty { return "{}" }
        let keys = dict.keys.sorted()
        var lines = ["{"]
        for i in 0..<keys.count {
            let key = keys[i]
            let val = stringify(dict[key]!, level: level + 1)
            let comma = i < keys.count - 1 ? "," : ""
            lines.append("\(nextIndent)\"\(escapeString(key))\": \(val)\(comma)")
        }
        lines.append("\(indent)}")
        return lines.joined(separator: "\n")
    }

    if let arr = value as? [Any] {
        if arr.isEmpty { return "[]" }
        var lines = ["["]
        for i in 0..<arr.count {
            let val = stringify(arr[i], level: level + 1)
            let comma = i < arr.count - 1 ? "," : ""
            lines.append("\(nextIndent)\(val)\(comma)")
        }
        lines.append("\(indent)]")
        return lines.joined(separator: "\n")
    }

    if let str = value as? String {
        return "\"\(escapeString(str))\""
    }

    if let num = value as? NSNumber {
        let type = String(cString: num.objCType)
        if type == "c" || type == "C" || type == "B" {
            return num.boolValue ? "true" : "false"
        }
        return "\(num)"
    }

    if value is NSNull {
        return "null"
    }

    return "null"
}

