use std::collections::BTreeMap;
use std::fs;

#[derive(Clone, Debug, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}
impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Self { bytes: s.as_bytes(), pos: 0 } }
    fn peek(&self) -> Option<u8> { self.bytes.get(self.pos).copied() }
    fn next(&mut self) -> Option<u8> { let c = self.peek(); if c.is_some() { self.pos += 1; } c }
    fn skip_ws(&mut self) { while matches!(self.peek(), Some(b' ' | b'\n' | b'\r' | b'\t')) { self.pos += 1; } }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Value::String(self.parse_string()?)),
            Some(b't') => { self.expect_literal(b"true")?; Ok(Value::Bool(true)) }
            Some(b'f') => { self.expect_literal(b"false")?; Ok(Value::Bool(false)) }
            Some(b'n') => { self.expect_literal(b"null")?; Ok(Value::Null) }
            Some(b'-') => Ok(Value::Number(self.parse_number()?)),
            Some(c) if c.is_ascii_digit() => Ok(Value::Number(self.parse_number()?)),
            Some(c) => Err(format!("unexpected char {}", c as char)),
            None => Err("unexpected end".into()),
        }
    }
    fn expect_literal(&mut self, lit: &[u8]) -> Result<(), String> {
        for &b in lit { if self.next() != Some(b) { return Err("literal mismatch".into()); } }
        Ok(())
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.next() != Some(b'"') { return Err("string start".into()); }
        let mut s = String::new();
        loop {
            let c = self.next().ok_or("unterminated string")?;
            match c {
                b'"' => return Ok(s),
                b'\\' => {
                    let esc = self.next().ok_or("bad escape")?;
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'b' => s.push('\x08'),
                        b'f' => s.push('\x0c'),
                        b'n' => s.push('\n'),
                        b'r' => s.push('\r'),
                        b't' => s.push('\t'),
                        b'u' => {
                            let mut hex = [0u8;4];
                            for i in 0..4 { hex[i]=self.next().ok_or("bad unicode")?; }
                            let code = String::from_utf8_lossy(&hex).parse::<u32>().map_err(|_| "bad hex")?;
                            if let Some(ch) = std::char::from_u32(code) { s.push(ch); } else { s.push('?'); }
                        }
                        _ => s.push(esc as char),
                    }
                }
                _ => s.push(c as char),
            }
        }
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while let Some(c) = self.peek() { if c.is_ascii_digit() { self.pos += 1; } else { break; } }
        if self.peek() == Some(b'.') { self.pos += 1; while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.pos+=1;} else {break;} } }
        if let Some(c)=self.peek() { if c==b'e'||c==b'E' { self.pos+=1; if let Some(s)=self.peek(){ if s==b'+'||s==b'-'{self.pos+=1;}} while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.pos+=1;} else {break;} } } }
        let num_str = std::str::from_utf8(&self.bytes[start..self.pos]).map_err(|_| "utf8")?;
        num_str.parse::<f64>().map_err(|_| "bad number".into())
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.next(); // [
        self.skip_ws();
        let mut arr = Vec::new();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Value::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("bad array".into()),
            }
        }
        Ok(Value::Array(arr))
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.next(); // {
        self.skip_ws();
        let mut map = BTreeMap::new();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Value::Object(map)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next() != Some(b':') { return Err("missing colon".into()); }
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("bad object".into()),
            }
        }
        Ok(Value::Object(map))
    }
}

fn merge(a: Value, b: Value) -> Value {
    match (a, b) {
        (Value::Object(mut ma), Value::Object(mb)) => {
            for (k, vb) in mb {
                if let Some(va) = ma.get(&k).cloned() {
                    let merged = merge(va, vb);
                    ma.insert(k, merged);
                } else {
                    ma.insert(k, vb);
                }
            }
            Value::Object(ma)
        }
        (Value::Array(mut aarr), Value::Array(barr)) => {
            for item in barr {
                if !aarr.contains(&item) { aarr.push(item); }
            }
            Value::Array(aarr)
        }
        (_, bval) => bval,
    }
}

fn serialize(v: &Value, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => if *b { "true".into() } else { "false".into() },
        Value::Number(n) => {
            if n.fract() == 0.0 && n.abs() < 1e15 { format!("{}", *n as i64) } else { n.to_string() }
        }
        Value::String(s) => escape_string(s),
        Value::Array(arr) => {
            if arr.is_empty() { return "[]".into(); }
            let mut out = String::from("[\n");
            for (i, item) in arr.iter().enumerate() {
                out.push_str(&"  ".repeat(indent+1));
                out.push_str(&serialize(item, indent+1));
                if i+1 < arr.len() { out.push_str(","); }
                out.push('\n');
            }
            out.push_str(&ind);
            out.push(']');
            out
        }
        Value::Object(map) => {
            if map.is_empty() { return "{}".into(); }
            let mut out = String::from("{\n");
            for (i, (k, val)) in map.iter().enumerate() {
                out.push_str(&"  ".repeat(indent+1));
                out.push_str(&escape_string(k));
                out.push_str(": ");
                match val {
                    Value::Object(_) | Value::Array(_) => {
                        out.push('\n');
                        out.push_str(&"  ".repeat(indent+2));
                        out.push_str(&serialize(val, indent+1));
                        if i+1 < map.len() { out.push_str(","); }
                        out.push('\n');
                    }
                    _ => {
                        out.push_str(&serialize(val, indent+1));
                        if i+1 < map.len() { out.push_str(","); }
                        out.push('\n');
                    }
                }
            }
            out.push_str(&ind);
            out.push('}');
            out
        }
    }
}

fn escape_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

fn parse_json(s: &str) -> Value {
    let mut p = Parser::new(s);
    let v = p.parse_value().expect("parse error");
    p.skip_ws();
    v
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";
    let a_str = fs::read_to_string(path_a).expect("read a");
    let b_str = fs::read_to_string(path_b).expect("read b");
    let a_val = parse_json(&a_str);
    let b_val = parse_json(&b_str);
    let merged = merge(a_val, b_val);
    let out = serialize(&merged, 0);
    println!("{}", out);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <limits.h>

typedef struct {
    char *rel_path;
    char *ext;
    long lines;
    long chars;
} FileEntry;

static FileEntry *entries = NULL;
static size_t entry_count = 0;
static size_t entry_cap = 0;
static long total_files = 0;
static long total_lines_all = 0;
static long total_chars_all = 0;

static void ensure_capacity(void) {
    if (entry_count >= entry_cap) {
        size_t new_cap = entry_cap ? entry_cap * 2 : 256;
        FileEntry *tmp = realloc(entries, new_cap * sizeof(FileEntry));
        if (!tmp) { perror("realloc"); exit(1); }
        entries = tmp;
        entry_cap = new_cap;
    }
}

static char *get_extension(const char *rel_path) {
    const char *slash = strrchr(rel_path, '/');
    const char *base = slash ? slash + 1 : rel_path;
    const char *dot = strrchr(base, '.');
    if (dot && dot != base && *(dot + 1) != '\0') {
        size_t len = strlen(dot);
        char *ext = malloc(len + 1);
        strcpy(ext, dot);
        return ext;
    }
    char *ext = malloc(1);
    ext[0] = '\0';
    return ext;
}

static void count_file(const char *path, long *lines_out, long *chars_out) {
    FILE *f = fopen(path, "rb");
    if (!f) { *lines_out = 0; *chars_out = 0; return; }
    unsigned char buf[8192];
    size_t n;
    long lines = 0;
    long chars = 0;
    int last = 0;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) {
        chars += n;
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') lines++;
            last = buf[i];
        }
    }
    fclose(f);
    if (chars > 0 && last != '\n') lines++;
    *lines_out = lines;
    *chars_out = chars;
}

static void add_entry(const char *rel_path, const char *ext, long lines, long chars) {
    ensure_capacity();
    entries[entry_count].rel_path = strdup(rel_path);
    entries[entry_count].ext = strdup(ext);
    entries[entry_count].lines = lines;
    entries[entry_count].chars = chars;
    entry_count++;
    total_files++;
    total_lines_all += lines;
    total_chars_all += chars;
}

static void walk_dir(const char *abs_path, const char *rel_path) {
    DIR *d = opendir(abs_path);
    if (!d) return;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        char child_abs[PATH_MAX];
        snprintf(child_abs, PATH_MAX, "%s/%s", abs_path, de->d_name);
        char child_rel[PATH_MAX];
        if (rel_path[0] == '\0')
            snprintf(child_rel, PATH_MAX, "%s", de->d_name);
        else
            snprintf(child_rel, PATH_MAX, "%s/%s", rel_path, de->d_name);
        struct stat st;
        if (lstat(child_abs, &st) != 0) continue;
        if (S_ISLNK(st.st_mode)) continue;
        if (S_ISDIR(st.st_mode)) {
            walk_dir(child_abs, child_rel);
        } else if (S_ISREG(st.st_mode)) {
            long lines, chars;
            count_file(child_abs, &lines, &chars);
            char *ext = get_extension(child_rel);
            add_entry(child_rel, ext, lines, chars);
            free(ext);
        }
    }
    closedir(d);
}

static int cmp_entries(const void *a, const void *b) {
    const FileEntry *ea = (const FileEntry *)a;
    const FileEntry *eb = (const FileEntry *)b;
    int c = strcmp(ea->ext, eb->ext);
    if (c != 0) return c;
    return strcmp(ea->rel_path, eb->rel_path);
}

int main(void) {
    const char *base = "/tmp/…/project_tree";
    walk_dir(base, "");
    if (entry_count > 0) qsort(entries, entry_count, sizeof(FileEntry), cmp_entries);

