}

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;
        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) {
        Path root = Paths.get("/tmp/…/project_tree");
        Map<String, List<FileInfo>> byExt = new TreeMap<>();
        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        if (Files.isDirectory(root)) {
            try {
                Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
                    @Override
                    public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                        try {
                            if (Files.isSymbolicLink(dir)) return FileVisitResult.SKIP_SUBTREE;
                        } catch (Exception e) {}
                        return FileVisitResult.CONTINUE;
                    }

                    @Override
                    public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                        try {
                            if (Files.isSymbolicLink(file)) return FileVisitResult.CONTINUE;
                            if (!attrs.isRegularFile()) return FileVisitResult.CONTINUE;
                            String fileName = file.getFileName().toString();
                            String ext;
                            int idx = fileName.lastIndexOf('.');
                            if (idx >= 0 && idx < fileName.length() - 1) {
                                ext = fileName.substring(idx);
                            } else {
                                ext = "";
                            }
                            String rel = root.relativize(file).toString().replace(File.separatorChar, '/');
                            long chars = Files.size(file);
                            long lines = 0;
                            try (BufferedReader br = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
                                while (br.readLine() != null) lines++;
                            } catch (Exception e) {
                                // fallback count by bytes for binary files
                                try {
                                    byte[] data = Files.readAllBytes(file);
                                    for (byte b : data) if (b == '\n') lines++;
                                    if (data.length > 0 && data[data.length - 1] != '\n') lines++;
                                } catch (Exception ignored) {}
                            }
                            FileInfo fi = new FileInfo(rel, lines, chars);
                            byExt.computeIfAbsent(ext, k -> new ArrayList<>()).add(fi);
                            totalFiles++;
                            totalLines += lines;
                            totalChars += chars;
                        } catch (IOException ignored) {}
                        return FileVisitResult.CONTINUE;
                    }
                });
            } catch (IOException ignored) {}
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();
        boolean firstExt = true;
        for (Map.Entry<String, List<FileInfo>> e : byExt.entrySet()) {
            List<FileInfo> list = e.getValue();
            list.sort(Comparator.comparing(fi -> fi.relPath));
            long filesCount = list.size();
            long sumLines = 0;
            long sumChars = 0;
            for (FileInfo fi : list) {
                sumLines += fi.lines;
                sumChars += fi.chars;
            }
            System.out.println("Extension: " + e.getKey());
            System.out.println("  Files: " + filesCount);
            System.out.println("  Total Lines: " + sumLines);
            System.out.println("  Total Characters: " + sumChars);
            for (FileInfo fi : list) {
                System.out.println("    " + fi.relPath + ": " + fi.lines + " lines, " + fi.chars + " chars");
            }
        }
        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }
}

