import * as path from 'path';

const ROOT = '/tmp/…/project_tree';

type FileInfo = { relPath: string; lines: number; chars: number };

async function walk(current: string, relBase: string, map: Map<string, FileInfo[]>): Promise<void> {
  let entries: fs.Dirent[];
  try {
    entries = await fs.readdir(current, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;
    const absPath = path.join(current, entry.name);
    const relPath = path.posix.join(relBase, entry.name);
    if (entry.isDirectory()) {
      await walk(absPath, relPath, map);
    } else if (entry.isFile()) {
      try {
        const buf = await fs.readFile(absPath);
        const chars = buf.length;
        let lines = 0;
        if (chars > 0) {
          let nl = 0;
          for (let i = 0; i < buf.length; i++) {
            if (buf[i] === 0x0a) nl++;
          }
          lines = buf[buf.length - 1] === 0x0a ? nl : nl + 1;
        }
        const ext = path.extname(entry.name) || '';
        const arr = map.get(ext) ?? [];
        arr.push({ relPath, lines, chars });
        map.set(ext, arr);
      } catch {}
    }
  }
}

async function main() {
  const map = new Map<string, FileInfo[]>();
  await walk(ROOT, '', map);

  console.log('=== File Tree Analysis ===');
  console.log('');

  const extensions = Array.from(map.keys()).sort();
  for (const ext of extensions) {
    const files = map.get(ext)!;
    files.sort((a, b) => a.relPath.localeCompare(b.relPath));
    const totalFiles = files.length;
    const totalLines = files.reduce((s, f) => s + f.lines, 0);
    const totalChars = files.reduce((s, f) => s + f.chars, 0);
    console.log(`Extension: ${ext}`);
    console.log(`  Files: ${totalFiles}`);
    console.log(`  Total Lines: ${totalLines}`);
    console.log(`  Total Characters: ${totalChars}`);
    for (const f of files) {
      console.log(`    ${f.relPath}: ${f.lines} lines, ${f.chars} chars`);
    }
  }

  let allFiles = 0;
  let allLines = 0;
  let allChars = 0;
  for (const files of map.values()) {
    allFiles += files.length;
    for (const f of files) {
      allLines += f.lines;
      allChars += f.chars;
    }
  }
  console.log('');
  console.log(`Total: ${allFiles} files, ${allLines} lines, ${allChars} characters`);
}

