function formatRow(row: number[]): string {
  const formatted = row.map(v => v.toString().padStart(4)).join(' ');
  return '  ' + formatted;
}

function printMatrix(name: string, mat: number[][]) {
  console.log(name);
  for (const row of mat) {
    console.log(formatRow(row));
  }
}

function multiply(A: number[][], B: number[][]): number[][] {
  const rowsA = A.length;
  const colsA = A[0].length;
  const colsB = B[0].length;
  const C: number[][] = Array.from({ length: rowsA }, () => Array(colsB).fill(0));
  for (let i = 0; i < rowsA; i++) {
    for (let k = 0; k < colsA; k++) {
      for (let j = 0; j < colsB; j++) {
        C[i][j] += A[i][k] * B[k][j];
      }
    }
  }
  return C;
}

function determinant3(m: number[][]): number {
  const a = m[0][0], b = m[0][1], c = m[0][2];
  const d = m[1][0], e = m[1][1], f = m[1][2];
  const g = m[2][0], h = m[2][1], i = m[2][2];
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

