use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

struct FileInfo {
    rel_path: String,
    lines: u64,
    chars: u64,
}

fn walk_dir(current: &Path, base: &Path, map: &mut HashMap<String, Vec<FileInfo>>, total_files: &mut u64, total_lines: &mut u64, total_chars: &mut u64) {
    if let Ok(entries) = fs::read_dir(current) {
        for entry_res in entries {
            if let Ok(entry) = entry_res {
                let path = entry.path();
                if let Ok(ft) = entry.file_type() {
                    if ft.is_symlink() {
                        continue;
                    }
                    if ft.is_dir() {
                        walk_dir(&path, base, map, total_files, total_lines, total_chars);
                    } else if ft.is_file() {
                        if let Ok(rel) = path.strip_prefix(base) {
                            let rel_str = rel.to_string_lossy().replace("\\", "/").to_string();
                            let ext = path.extension().and_then(|e| e.to_str()).map(|s| format!(".{}", s)).unwrap_or_else(|| "".to_string());
                            let lines = if let Ok(data) = fs::read(&path) {
                                let nl = data.iter().filter(|&&b| b == b'\n').count() as u64;
                                if data.is_empty() { 0 } else if data.last() == Some(&b'\n') { nl } else { nl + 1 }
                            } else { 0 };
                            let chars = fs::metadata(&path).map(|m| m.len()).unwrap_or(0);
                            map.entry(ext.clone()).or_default().push(FileInfo { rel_path: rel_str, lines, chars });
                            *total_files += 1;
                            *total_lines += lines;
                            *total_chars += chars as u64;
                        }
                    }
                }
            }
        }
    }
}

fn main() {
    let base = PathBuf::from("/tmp/…/project_tree");
    let mut map: HashMap<String, Vec<FileInfo>> = HashMap::new();
    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    walk_dir(&base, &base, &mut map, &mut total_files, &mut total_lines, &mut total_chars);

    let mut exts: Vec<String> = map.keys().cloned().collect();
    exts.sort();

    println!("=== File Tree Analysis ===");
    println!();

    for (i, ext) in exts.iter().enumerate() {
        let files = map.get(ext).unwrap();
        let mut files_sorted = files.clone();
        files_sorted.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));
        let files_count = files_sorted.len() as u64;
        let sum_lines: u64 = files_sorted.iter().map(|f| f.lines).sum();
        let sum_chars: u64 = files_sorted.iter().map(|f| f.chars).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", files_count);
        println!("  Total Lines: {}", sum_lines);
        println!("  Total Characters: {}", sum_chars);
        for f in &files_sorted {
            println!("    {}: {} lines, {} chars", f.rel_path, f.lines, f.chars);
        }
        // no blank line between groups
        let _ = i;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

