#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 3;
    int *A = malloc(n * n * sizeof(int));
    int *B = malloc(n * n * sizeof(int));
    int *C = malloc(n * n * sizeof(int));
    if (!A || !B || !C) return 1;

    int a_vals[9] = {1,2,3,4,5,6,7,8,9};
    int b_vals[9] = {9,8,7,6,5,4,3,2,1};
    for (int i = 0; i < n * n; i++) {
        A[i] = a_vals[i];
        B[i] = b_vals[i];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = 0;
            for (int k = 0; k < n; k++) {
                sum += A[i * n + k] * B[k * n + j];
            }
            C[i * n + j] = sum;
        }
    }

    long long det = 0;
    {
        long long c00 = C[0], c01 = C[1], c02 = C[2];
        long long c10 = C[3], c11 = C[4], c12 = C[5];
        long long c20 = C[6], c21 = C[7], c22 = C[8];
        det = c00 * (c11 * c22 - c12 * c21)
            - c01 * (c10 * c22 - c12 * c20)
            + c02 * (c10 * c21 - c11 * c20);
    }

    printf("=== Matrix Operations ===\n\n");
    printf("Matrix A:\n");
    for (int i = 0; i < n; i++) {
        printf("  ");
        for (int j = 0; j < n; j++) {
            printf("%4d", A[i * n + j]);
            if (j < n - 1) printf(" ");
        }
        printf("\n");
    }
    printf("\n");
    printf("Matrix B:\n");
    for (int i = 0; i < n; i++) {
        printf("  ");
        for (int j = 0; j < n; j++) {
            printf("%4d", B[i * n + j]);
            if (j < n - 1) printf(" ");
        }
        printf("\n");
    }
    printf("\n");
    printf("A x B =\n");
    for (int i = 0; i < n; i++) {
        printf("  ");
        for (int j = 0; j < n; j++) {
            printf("%4d", C[i * n + j]);
            if (j < n - 1) printf(" ");
        }
        printf("\n");
    }
    printf("\n");
    printf("Determinant: %lld\n", det);

    free(A);
    free(B);
    free(C);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define INF 1000000000000LL

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    if (!buf) { fclose(f); return NULL; }
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    if (out_len) *out_len = sz;
    return buf;
}

static char *parse_quoted(char *p) {
    if (*p != '"') return NULL;
    p++;
    char *s = p;
    while (*p && *p != '"') p++;
    size_t len = p - s;
    char *out = malloc(len + 1);
    memcpy(out, s, len);
    out[len] = '\0';
    return out;
}

int main(void) {
    const char *path = "/tmp/…/graph.json";
    size_t len;
    char *buf = read_file(path, &len);
    if (!buf) return 1;

    int nodeCap = 256;
    char **nodes = malloc(nodeCap * sizeof(char*));
    int nodeCount = 0;

    char *p = strstr(buf, "\"nodes\"");
    if (p) {
        char *b = strchr(p, '[');
        if (b) {
            b++;
            while (*b && *b != ']') {
                while (*b && (isspace((unsigned char)*b) || *b == ',')) b++;
                if (*b == '"') {
                    char *name = parse_quoted(b);
                    if (name) {
                        if (nodeCount >= nodeCap) {
                            nodeCap *= 2;
                            nodes = realloc(nodes, nodeCap * sizeof(char*));
                        }
                        nodes[nodeCount++] = name;
                        while (*b && *b != '"') b++;
                        if (*b == '"') b++;
                    }
                } else b++;
            }
        }
    }

    int srcIdx = -1;
    for (int i = 0; i < nodeCount; i++) {
        if (strcmp(nodes[i], "A") == 0) { srcIdx = i; break; }
    }
    if (srcIdx == -1) srcIdx = 0;

    long long **adj = malloc(nodeCount * sizeof(long long*));
    for (int i = 0; i < nodeCount; i++) {
        adj[i] = malloc(nodeCount * sizeof(long long));
        for (int j = 0; j < nodeCount; j++) adj[i][j] = -1;
        adj[i][i] = 0;
    }

    char *e = strstr(buf, "\"edges\"");
    if (e) {
        char *b = strchr(e, '[');
        if (b) {
            b++;
            while (*b && *b != ']') {
                if (*b == '{') {
                    char *obj_end = strchr(b, '}');
                    if (!obj_end) break;
                    char *fromPos = strstr(b, "\"from\"");
                    char *toPos = strstr(b, "\"to\"");
                    char *weightPos = strstr(b, "\"weight\"");
                    char *fromName = NULL, *toName = NULL;
                    long long weight = 0;
                    if (fromPos && fromPos < obj_end) {
                        char *colon = strchr(fromPos, ':');
                        if (colon) {
                            colon++;
                            while (*colon && isspace((unsigned char)*colon)) colon++;
                            if (*colon == '"') fromName = parse_quoted(colon);
                        }
                    }
                    if (toPos && toPos < obj_end) {
                        char *colon = strchr(toPos, ':');
                        if (colon) {
                            colon++;
                            while (*colon && isspace((unsigned char)*colon)) colon++;
                            if (*colon == '"') toName = parse_quoted(colon);
                        }
                    }
                    if (weightPos && weightPos < obj_end) {
                        char *colon = strchr(weightPos, ':');
                        if (colon) {
                            colon++;
                            while (*colon && isspace((unsigned char)*colon)) colon++;
                            int sign = 1;
                            if (*colon == '-') { sign = -1; colon++; }
                            long long val = 0;
                            while (*colon && isdigit((unsigned char)*colon)) {
                                val = val * 10 + (*colon - '0');
                                colon++;
                            }
                            weight = sign * val;
                        }
                    }
                    if (fromName && toName) {
                        int i = -1, j = -1;
                        for (int k = 0; k < nodeCount; k++) {
                            if (strcmp(nodes[k], fromName) == 0) i = k;
                            if (strcmp(nodes[k], toName) == 0) j = k;
                        }
                        if (i != -1 && j != -1) {
                            if (adj[i][j] == -1 || weight < adj[i][j]) {
                                adj[i][j] = adj[j][i] = weight;
                            }
                        }
                    }
                    free(fromName); free(toName);
                    b = obj_end + 1;
                } else b++;
            }
        }
    }

    long long *dist = malloc(nodeCount * sizeof(long long));
    int *vis = calloc(nodeCount, sizeof(int));
    for (int i = 0; i < nodeCount; i++) dist[i] = INF;
    dist[srcIdx] = 0;

    for (int iter = 0; iter < nodeCount; iter++) {
        int u = -1;
        long long best = INF;
        for (int i = 0; i < nodeCount; i++) {
            if (!vis[i] && dist[i] < best) { best = dist[i]; u = i; }
        }
        if (u == -1) break;
        vis[u] = 1;
        for (int v = 0; v < nodeCount; v++) {
            if (adj[u][v] != -1 && !vis[v]) {
                long long nd = dist[u] + adj[u][v];
                if (nd < dist[v]) dist[v] = nd;
            }
        }
    }

    char **sorted = malloc(nodeCount * sizeof(char*));
    for (int i = 0; i < nodeCount; i++) sorted[i] = nodes[i];
    int cmp_str(const void *a, const void *b){ return strcmp(*(const char**)a, *(const char**)b); }
    qsort(sorted, nodeCount, sizeof(char*), cmp_str);

    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < nodeCount; i++) {
        int idx = -1;
        for (int k = 0; k < nodeCount; k++) if (strcmp(nodes[k], sorted[i]) == 0) { idx = k; break; }
        long long d = (idx == -1) ? INF : dist[idx];
        if (d >= INF/2) d = -1;
        printf("A -> %s: %lld\n", sorted[i], d);
    }

    return 0;
}

