                        if (nodeCount >= nodeCap) {
                            nodeCap *= 2;
                            nodes = realloc(nodes, nodeCap * sizeof(char*));
                        }
                        nodes[nodeCount++] = name;
                        while (*b && *b != '"') b++;
                        if (*b == '"') b++;
                    }
                } else b++;
            }
        }
    }

