    for (int i = 0; i < nodeCount; i++) {
        if (strcmp(nodes[i], "A") == 0) { srcIdx = i; break; }
    }
    if (srcIdx == -1) srcIdx = 0;

    long long **adj = malloc(nodeCount * sizeof(long long*));
    for (int i = 0; i < nodeCount; i++) {
        adj[i] = malloc(nodeCount * sizeof(long long));
        for (int j = 0; j < nodeCount; j++) adj[i][j] = -1;
        adj[i][i] = 0;
    }

    char *e = strstr(buf, "\"edges\"");
    if (e) {
        char *b = strchr(e, '[');
        if (b) {
            b++;
            while (*b && *b != ']') {
                if (*b == '{') {
                    char *obj_end = strchr(b, '}');
                    if (!obj_end) break;
                    char *fromPos = strstr(b, "\"from\"");
                    char *toPos = strstr(b, "\"to\"");
                    char *weightPos = strstr(b, "\"weight\"");
                    char *fromName = NULL, *toName = NULL;
                    long long weight = 0;
                    if (fromPos && fromPos < obj_end) {
                        char *colon = strchr(fromPos, ':');
                        if (colon) {
                            colon++;
                            while (*colon && isspace((unsigned char)*colon)) colon++;
                            if (*colon == '"') fromName = parse_quoted(colon);
                        }
                    }
