                        if (colon) {
                            colon++;
                            while (*colon && isspace((unsigned char)*colon)) colon++;
                            int sign = 1;
                            if (*colon == '-') { sign = -1; colon++; }
                            long long val = 0;
                            while (*colon && isdigit((unsigned char)*colon)) {
                                val = val * 10 + (*colon - '0');
                                colon++;
                            }
                            weight = sign * val;
                        }
                    }
                    if (fromName && toName) {
                        int i = -1, j = -1;
                        for (int k = 0; k < nodeCount; k++) {
                            if (strcmp(nodes[k], fromName) == 0) i = k;
                            if (strcmp(nodes[k], toName) == 0) j = k;
                        }
                        if (i != -1 && j != -1) {
                            if (adj[i][j] == -1 || weight < adj[i][j]) {
                                adj[i][j] = adj[j][i] = weight;
                            }
                        }
                    }
                    free(fromName); free(toName);
                    b = obj_end + 1;
                } else b++;
            }
        }
    }

    long long *dist = malloc(nodeCount * sizeof(long long));
    int *vis = calloc(nodeCount, sizeof(int));
    for (int i = 0; i < nodeCount; i++) dist[i] = INF;
    dist[srcIdx] = 0;

    for (int iter = 0; iter < nodeCount; iter++) {
        int u = -1;
        long long best = INF;
        for (int i = 0; i < nodeCount; i++) {
            if (!vis[i] && dist[i] < best) { best = dist[i]; u = i; }
        }
        if (u == -1) break;
        vis[u] = 1;
        for (int v = 0; v < nodeCount; v++) {
            if (adj[u][v] != -1 && !vis[v]) {
                long long nd = dist[u] + adj[u][v];
                if (nd < dist[v]) dist[v] = nd;
            }
        }
    }

    char **sorted = malloc(nodeCount * sizeof(char*));
    for (int i = 0; i < nodeCount; i++) sorted[i] = nodes[i];
    qsort(sorted, nodeCount, sizeof(char*), cmp_str);

