    for (int i = 0; i < nodeCount; i++) {
        int idx = -1;
        for (int k = 0; k < nodeCount; k++) if (strcmp(nodes[k], sorted[i]) == 0) { idx = k; break; }
        long long d = (idx == -1) ? INF : dist[idx];
        if (d >= INF/2) d = -1;
        printf("A -> %s: %lld\n", sorted[i], d);
    }

    return 0;
}

import Foundation

let rootPath = "/tmp/…/project_tree"
let rootURL = URL(fileURLWithPath: rootPath)

var filesByExt: [String: [(relPath: String, lines: Int, chars: Int)]] = [:]
var totalFiles = 0
var totalLines = 0
var totalChars = 0

let fm = FileManager.default
guard let enumerator = fm.enumerator(at: rootURL, includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey], options: [.skipsHiddenFiles]) else {
    print("=== File Tree Analysis ===")
    print("")
    print("Total: 0 files, 0 lines, 0 characters")
    exit(0)
}

for case let url as URL in enumerator {
    var isSymlink = false
    var isRegular = false
    do {
        let vals = try url.resourceValues(forKeys: [.isSymbolicLinkKey, .isRegularFileKey])
        isSymlink = vals.isSymbolicLink ?? false
        isRegular = vals.isRegularFile ?? false
    } catch { continue }
    if isSymlink { continue }
    if !isRegular { continue }

    let relPath = String(url.path.dropFirst(rootURL.path.count)).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
    guard !relPath.isEmpty else { continue }

    let extRaw = url.pathExtension.lowercased()
    let ext = extRaw.isEmpty ? "" : ".\(extRaw)"

    let attrs = try? fm.attributesOfItem(atPath: url.path)
    let chars = (attrs?[.size] as? NSNumber)?.intValue ?? 0

    var lines = 0
    if chars > 0 {
        if let handle = try? FileHandle(forReadingFrom: url) {
            defer { try? handle.close() }
            var newlineCount = 0
            var lastByte: UInt8 = 0
            let chunkSize = 8192
            while true {
                let data = try? handle.read(upToCount: chunkSize)
                if data == nil || data!.isEmpty { break }
                for b in data! {
                    lastByte = b
                    if b == 10 { newlineCount += 1 }
                }
            }
            if lastByte != 10 {
                lines = newlineCount + 1
            } else {
                lines = newlineCount > 0 ? newlineCount : 1
            }
        }
    }

    filesByExt[ext, default: []].append((relPath: relPath, lines: lines, chars: chars))
    totalFiles += 1
    totalLines += lines
    totalChars += chars
}

print("=== File Tree Analysis ===")
print("")

let sortedExts = filesByExt.keys.sorted()
for ext in sortedExts {
    var entries = filesByExt[ext]!
    entries.sort { $0.relPath < $1.relPath }
    let filesCount = entries.count
    let sumLines = entries.reduce(0) { $0 + $1.lines }
    let sumChars = entries.reduce(0) { $0 + $1.chars }
    print("Extension: \(ext)")
    print("  Files: \(filesCount)")
    print("  Total Lines: \(sumLines)")
    print("  Total Characters: \(sumChars)")
    for e in entries {
        print("    \(e.relPath): \(e.lines) lines, \(e.chars) chars")
    }
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

