use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;
use std::fs;

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("cannot read file");

    // parse nodes
    let nodes_section = content.find("\"nodes\"").expect("nodes not found");
    let after_nodes = &content[nodes_section..];
    let b_start = after_nodes.find('[').expect("nodes [");
    let b_end = after_nodes.find(']').expect("nodes ]");
    let nodes_inner = &after_nodes[b_start + 1..b_end];
    let mut nodes: Vec<String> = nodes_inner
        .split(',')
        .map(|s| s.trim().trim_matches('"').to_string())
        .filter(|s| !s.is_empty())
        .collect();
    nodes.sort();
    nodes.dedup();

    // parse edges
    let edges_section = content.find("\"edges\"").expect("edges not found");
    let after_edges = &content[edges_section..];
    let e_b_start = after_edges.find('[').expect("edges [");
    let e_b_end_rel = after_edges[e_b_start + 1..].find(']').expect("edges ]");
    let e_b_end = e_b_start + 1 + e_b_end_rel;
    let edges_inner = &after_edges[e_b_start + 1..e_b_end];

    let mut adj: HashMap<String, Vec<(String, u64)>> = HashMap::new();
    for n in &nodes {
        adj.entry(n.clone()).or_insert_with(Vec::new);
    }

    let mut search_start = 0;
    let edges_str = edges_inner;
    while let Some(rel_start) = edges_str[search_start..].find('{') {
        let start = search_start + rel_start;
        let rest = &edges_str[start..];
        let rel_end = rest.find('}').expect("object end");
        let end = start + rel_end;
        let obj = &edges_str[start..=end];

        if let Some((from, to, w)) = parse_edge(obj) {
            adj.entry(from.clone()).or_default().push((to.clone(), w));
            adj.entry(to.clone()).or_default().push((from.clone(), w));
        }
        search_start = end + 1;
    }

    // Dijkstra from A
    let start_node = "A".to_string();
    let mut dist: HashMap<String, u64> = HashMap::new();
    for n in &nodes {
        dist.insert(n.clone(), u64::MAX);
    }
    if dist.contains_key(&start_node) {
        dist.insert(start_node.clone(), 0);
    }

    let mut heap = BinaryHeap::new();
    heap.push((Reverse(0), start_node.clone()));

    while let Some((Reverse(d), u)) = heap.pop() {
        if d != *dist.get(&u).unwrap_or(&u64::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&u) {
            for (v, w) in neighbors {
                let nd = d.saturating_add(*w);
                if nd < *dist.get(v).unwrap_or(&u64::MAX) {
                    dist.insert(v.clone(), nd);
                    heap.push((Reverse(nd), v.clone()));
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===\n");
    for n in nodes {
        let d = dist.get(&n).copied().unwrap_or(u64::MAX);
        if d == u64::MAX {
            println!("A -> {}: unreachable", n);
        } else {
            println!("A -> {}: {}", n, d);
        }
    }
}

fn parse_edge(obj: &str) -> Option<(String, String, u64)> {
    let from_key = "\"from\":\"";
    let to_key = "\"to\":\"";
    let weight_key = "\"weight\":";

    let from_start = obj.find(from_key)? + from_key.len();
    let from_end = obj[from_start..].find('"')? + from_start;
    let from = obj[from_start..from_end].to_string();

    let to_start = obj.find(to_key)? + to_key.len();
    let to_end = obj[to_start..].find('"')? + to_start;
    let to = obj[to_start..to_end].to_string();

    let w_start = obj.find(weight_key)? + weight_key.len();
    let w_rest = &obj[w_start..];
    let w_end = w_rest.find(|c: char| c == ',' || c == '}' || c.is_whitespace()).unwrap_or(w_rest.len());
    let w_str = w_rest[..w_end].trim();
    let w = w_str.parse::<u64>().ok()?;

    Some((from, to, w))
}

